// Single source for the home view's static parts AND the generated SKILL.md
// (AXI principle 7). Edit here; skills/diagram-axi/SKILL.md is
// regenerated by `npm run skill:gen` and CI fails if it drifts
// (`npm run skill:check`).

import { homedir } from "node:os";
import { ROUTE_LIMITS } from "../engines/route.js";
import { renderSlice } from "../guide/slices.js";
import { MAX_LINE } from "../lint/rules.js";
import { emitList } from "../output/toon.js";

export const DESCRIPTION =
  "Turn a compact text description of boxes and arrows into an editable diagram file (Excalidraw, D2 or Mermaid) plus PNG/SVG renders, offline";

export const SPEC_VERSION = "axi/1.0-2026-07";

/** Skill trigger text: what the model matches on to load SKILL.md. */
export const SKILL_DESCRIPTION =
  "Create an Excalidraw diagram, architecture diagram, flowchart or hand-drawn style diagram from a compact text DSL: writes an editable .excalidraw file and renders PNG/SVG offline. Also draws sequence, class, ER, state, timeline, commit-history and mind-map diagrams (D2, Mermaid). Use when asked to draw, diagram or sketch boxes and arrows, system or cloud architecture, pipelines, flows, org charts, Mermaid for a README, or how a TS/JS codebase's modules import each other.";

/** Three short lines of DSL shown on the home view; test/guide.test.ts parses them. */
export const DSL_TEASER = ["api[API] -> db[(Postgres)] : SQL", "web[Web], mobile[Mobile] -> api : HTTPS", "api[API] :purple,bold"];

export function collapseHome(path: string): string {
  const home = homedir();
  return path.startsWith(home) ? "~" + path.slice(home.length) : path;
}

/** Full tool reference for `diagram-axi --help`. */
export function rootHelpText(): string {
  const commands = emitList(
    "commands",
    [
      { command: "draw", summary: "DSL, .d2 or .mmd file (or stdin) to a diagram file [+ png/svg]" },
      { command: "render", summary: ".excalidraw, .d2 or .mmd to png/svg" },
      { command: "inspect", summary: "aggregates of a scene, DSL or native file" },
      { command: "check", summary: "lint a DSL file, compile-check a native one" },
      { command: "extract", summary: "(experimental) TS/JS folder to an import-graph .exd plus a file map" },
      { command: "syntax", summary: "DSL, d2, mermaid and routing reference slices" },
      { command: "engines", summary: "engine status and versions; engines install d2" },
    ],
    ["command", "summary"],
  );
  const flags = emitList(
    "flags",
    [
      { flag: "--help", default: "", description: "show help for any command" },
      { flag: "--version", default: "", description: "print the tool version" },
    ],
    ["flag", "default", "description"],
  );
  return [
    `diagram-axi: ${DESCRIPTION}`,
    commands,
    flags,
    "examples[3]:",
    "  diagram-axi draw diagram.exd --png",
    "  diagram-axi draw login.mmd --png",
    "  diagram-axi syntax example",
  ].join("\n");
}

/** The static SKILL.md: golden path and the example slice, zero-install command forms. */
export function renderSkill(): string {
  const tool = "npx -y diagram-axi";
  const frontmatter = ["---", "name: diagram-axi", `description: "${SKILL_DESCRIPTION.replace(/"/g, "'")}"`, "---"].join("\n");
  const example = renderSlice("example", tool) as string;
  const body = [
    "# diagram-axi",
    "",
    `${DESCRIPTION}. Run everything with npx; no install, no account.`,
    "",
    "## Golden path",
    "",
    "1. Read the DSL: `" + tool + " syntax example` (details: `" + tool + " syntax nodes|edges|groups|style`).",
    "2. Read the authoring limits: `" + tool + " syntax tips` (<= 2 arrows per node pair, <= 8 per node, 3-word edge labels, <= ~25 nodes).",
    "3. Write the diagram to `diagram.exd` (a few lines per box and arrow).",
    "4. Lint it: `" + tool + " check diagram.exd`; fix every warning (each carries a paste-able `suggestion`) before drawing.",
    "5. Draw it: `" + tool + " draw diagram.exd --png` writes `diagram.excalidraw` and `diagram.png`. A parse error prints `line:col`, the token and a fix; edit and rerun (`--force` overwrites). Fix any `quality:` rows (each has a `fix`) and rerun before rendering the final PNG. If `check` printed `engine: suggest d2`, draw with `--engine d2` (or `--engine auto`) unless the user asked for an editable Excalidraw file (then add `--target editable`, which keeps excalidraw).",
    "6. Verify: `" + tool + " inspect diagram.excalidraw` (counts, bounds, unresolved refs), then look at the PNG.",
    "",
    "`--png` / `--svg` need Chrome, Edge, Chromium or Firefox already installed (none is downloaded); without them `draw` still writes the editable `.excalidraw`, which opens at excalidraw.com. `render x.excalidraw --png` re-renders.",
    "",
    "## Choose the engine",
    "",
    "Default is excalidraw (editable, hand-drawn look). The tool recommends but never switches silently; `--engine excalidraw|d2|mermaid` is explicit, `--engine auto` follows the recommendation.",
    "",
    "| Need | Engine |",
    "|---|---|",
    "| boxes and arrows that fit (<= 25 nodes, sparse, short labels) | excalidraw: `.exd` |",
    "| sequence, class, ER/SQL tables | d2: write `.d2` |",
    "| state, timeline, commit history, mind map | mermaid: write `.mmd` |",
    "| dense or large graph | d2: `draw x.exd --engine d2` |",
    "| diagram for a README or GitHub | mermaid: `draw x.exd --target markdown` |",
    "",
    "README/GitHub output wins over every other row, kind rows included: an ER or sequence diagram for a README is mermaid `.mmd`.",
    "",
    "`check` and `draw` print `engine: suggest d2 (reason); add --engine d2` when a graph outgrows excalidraw; no `engine:` line means the default is fine. A `.d2` or `.mmd` file picks its own engine and is never rewritten: `" + tool + " draw login.mmd --png` writes `login.svg` and `login.png` beside it (d2 and mermaid always write SVG). Check native files with `check`.",
    "",
    "Read the syntax slice before writing native source: `" + tool + " syntax d2 sequence|class|erd|style|example`, `" + tool + " syntax mermaid state|timeline|gitgraph|mindmap|example`, `" + tool + " syntax routing`. `" + tool + " engines` shows status; PNG needs a browser, or the optional d2 binary (`engines install d2`).",
    "",
    "To learn a TS/JS codebase (experimental): `" + tool + " extract src` writes `imports.exd` (+ a file map; green = entry or --focus file, yellow = hub `used by N`); draw it following its `engine:` line (dense or wide graphs say d2); `--focus <file>` zooms in (`syntax extract`).",
    "",
    "## Known weaknesses (measured on held-out QA)",
    "",
    `- excalidraw: hubs with > ${ROUTE_LIMITS.degree} arrows, > ${ROUTE_LIMITS.parallel} arrows between one pair, labels over ${MAX_LINE} chars per line and > ${ROUTE_LIMITS.crossGroup} cross-group edges come out tangled (stacked arrowheads, labels drifting onto other arrows). \`check\` flags each; shorten or regroup, but if the user wants the content kept as is (all nodes, full labels) follow \`engine: suggest d2\` instead. Keep it for <= ${ROUTE_LIMITS.nodes} nodes, short labels, or when the user must edit by hand.`,
    `- d2: still crowds arrowheads on hairballs (edges > ${ROUTE_LIMITS.edgeRatio} x nodes, 50+ nodes) and sets multi-line edge labels tight. Best for nested or cross-linked groups, hubs, parallel edges, sequence/class/ER.`,
    "- mermaid: weakest with groups (nested subgraphs, many cross-group edges), self-loops, and long single-word labels (wrap mid-word); unreadable past 50 nodes. Use it when the output must render in Markdown/GitHub or for state/timeline/gitgraph/mindmap; for a README with hubs or parallel edges it is as good as d2.",
    "- every engine: past ~50 nodes, or when d2 still crowds, suggest splitting the diagram; a merely dense or large graph goes to d2.",
    "",
    "## Example",
    "",
    "```",
    example,
    "```",
    "",
    "Every command has `--help`; exit codes 0 ok, 1 error, 2 usage; output is TOON.",
  ].join("\n");
  return [frontmatter, "", body, ""].join("\n");
}
